<?php
declare(strict_types=1);require dirname(__DIR__,2).'/app/bootstrap.php';require BASE_PATH.'/app/AdminUi.php';$user=Auth::requireLogin();Auth::requirePermission('reports.view');$pdo=Database::connection();$from=$_GET['from']??date('Y-m-01');$to=$_GET['to']??date('Y-m-d');$companyId=(int)($user['company_id']??0);
$where='DATE(b.created_at) BETWEEN ? AND ?';$args=[$from,$to];if(($user['role']??'')==='company_manager'){$where.=' AND t.company_id=?';$args[]=$companyId;}
if(isset($_GET['csv'])){header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="aslalmotasader-report.csv"');$o=fopen('php://output','w');fwrite($o,"\xEF\xBB\xBF");fputcsv($o,['المرجع','العميل','الهاتف','الشركة','المسار','عدد المسافرين','الحالة','تاريخ الطلب']);$q=$pdo->prepare("SELECT b.reference_code,c.full_name,c.phone,co.name company_name,CONCAT(o.name_ar,' - ',d.name_ar) route,b.passengers_count,b.status,b.created_at FROM bookings b JOIN customers c ON c.id=b.customer_id JOIN trips t ON t.id=b.trip_id JOIN companies co ON co.id=t.company_id JOIN cities o ON o.id=t.origin_city_id JOIN cities d ON d.id=t.destination_city_id WHERE {$where} ORDER BY b.id DESC");$q->execute($args);while($r=$q->fetch(PDO::FETCH_NUM))fputcsv($o,$r);fclose($o);exit;}
$q=$pdo->prepare("SELECT COUNT(*) total,COALESCE(SUM(b.passengers_count),0) passengers,SUM(b.status='confirmed') confirmed,SUM(b.status='new') fresh FROM bookings b JOIN trips t ON t.id=b.trip_id WHERE {$where}");$q->execute($args);$stats=$q->fetch();$q=$pdo->prepare("SELECT b.reference_code,c.full_name,c.phone,co.name company_name,o.name_ar origin_name,d.name_ar destination_name,b.passengers_count,b.status,b.created_at FROM bookings b JOIN customers c ON c.id=b.customer_id JOIN trips t ON t.id=b.trip_id JOIN companies co ON co.id=t.company_id JOIN cities o ON o.id=t.origin_city_id JOIN cities d ON d.id=t.destination_city_id WHERE {$where} ORDER BY b.id DESC LIMIT 1000");$q->execute($args);$rows=$q->fetchAll();admin_page_start('التقارير والإحصائيات',$user);echo '<section class="panel"><form class="inline" method="get"><label>من <input type="date" name="from" value="'.e($from).'"></label><label>إلى <input type="date" name="to" value="'.e($to).'"></label><button class="btn-sm">تطبيق</button><a class="admin-link" href="?from='.e($from).'&to='.e($to).'&csv=1">تصدير CSV</a></form></section><div class="stats" style="display:grid;grid-template-columns:repeat(4,1fr);gap:12px"><div class="panel">الحجوزات<strong style="display:block;font-size:28px">'.(int)$stats['total'].'</strong></div><div class="panel">المسافرون<strong style="display:block;font-size:28px">'.(int)$stats['passengers'].'</strong></div><div class="panel">المؤكدة<strong style="display:block;font-size:28px">'.(int)$stats['confirmed'].'</strong></div><div class="panel">الجديدة<strong style="display:block;font-size:28px">'.(int)$stats['fresh'].'</strong></div></div><section class="panel"><h2>تفاصيل الحجوزات</h2><table><thead><tr><th>المرجع</th><th>العميل</th><th>الهاتف</th><th>الشركة</th><th>المسار</th><th>المسافرون</th><th>الحالة</th><th>التاريخ</th></tr></thead><tbody>';foreach($rows as $r)echo '<tr><td>'.e($r['reference_code']).'</td><td>'.e($r['full_name']).'</td><td>'.e($r['phone']).'</td><td>'.e($r['company_name']).'</td><td>'.e($r['origin_name'].' - '.$r['destination_name']).'</td><td>'.(int)$r['passengers_count'].'</td><td>'.e($r['status']).'</td><td>'.e($r['created_at']).'</td></tr>';if(!$rows)echo '<tr><td colspan="8">لا توجد بيانات في الفترة.</td></tr>';echo '</tbody></table></section>';admin_page_end();
